@startuml

class School {
  + Name : string
}

abstract class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + EmailAddress : string
}

class Student extends Person {
}

class ClassGroup {
  + Name : string
}

abstract class Room {
  + Name : string
}

class Classroom extends Room {
  + Capacity : int
}

class Gym extends Room {
  + SizeInSquareMeters : float
}

class TeachingAssignment {
  + Hours : int
}

School "1" -- "*" Teacher : employs
School "1" -- "1" Teacher : principal
School "1" -- "*" Student : has
Student "1" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
Classroom "1" -- "1" ClassGroup : contains
Teacher "0..3" -- "*" School : works at
Teacher "1" -- "*" TeachingAssignment : performs
School "1" -- "*" TeachingAssignment : manages
Student "*" -- "1" TeachingAssignment : participates in

@enduml

